package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string
	TrIncome decimal.Decimal
}

var WsEofFlag string = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var TaxRecGlobal TaxRec

var inputFile *os.File
var scanner *bufio.Scanner

var const10000 = decimal.New(1000000, -2)
var const40000 = decimal.New(4000000, -2)
var const1000 = decimal.New(100000, -2)
var const7000 = decimal.New(700000, -2)
var rate10 = decimal.New(10, -2)
var rate20 = decimal.New(20, -2)
var rate30 = decimal.New(30, -2)

func pow10Decimal(exp int32) decimal.Decimal {
	return decimal.New(1, exp)
}

func storeNumeric(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	dTrunc := d.Truncate(scale)
	powScale := pow10Decimal(scale)
	powTotal := pow10Decimal(int32(intDigits) + scale)
	scaledInt := dTrunc.Mul(powScale).Truncate(0)
	if scaledInt.IsNegative() {
		absScaled := scaledInt.Abs()
		modAbs := absScaled.Mod(powTotal)
		resultScaled := modAbs.Neg()
		result := resultScaled.Div(powScale)
		return result.Truncate(scale)
	}
	mod := scaledInt.Mod(powTotal)
	result := mod.Div(powScale)
	return result.Truncate(scale)
}

func parseIncome(raw string) decimal.Decimal {
	s := strings.TrimSpace(raw)
	if s == "" {
		return decimal.Zero
	}
	cleaned := ""
	for _, ch := range s {
		if (ch >= '0' && ch <= '9') || ch == '-' {
			cleaned += string(ch)
		}
	}
	if cleaned == "" || cleaned == "-" {
		return decimal.Zero
	}
	n, err := strconv.ParseInt(cleaned, 10, 64)
	if err != nil {
		return decimal.Zero
	}
	return decimal.New(n, -2)
}

func formatEdited(val decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var intPat, decPat string
	if dotIdx != -1 {
		intPat = pic[:dotIdx]
		decPat = pic[dotIdx+1:]
	} else {
		intPat = pic
		decPat = ""
	}
	capInt := 0
	for _, ch := range intPat {
		if ch == 'Z' || ch == '9' {
			capInt++
		}
	}
	decPlaces := 0
	for _, ch := range decPat {
		if ch == 'Z' || ch == '9' {
			decPlaces++
		}
	}
	isNeg := val.Sign() < 0
	absVal := val.Abs()

	intPart := absVal.Truncate(0)
	fracPart := absVal.Sub(intPart)

	if capInt > 0 {
		powCap := pow10Decimal(int32(capInt))
		if intPart.Cmp(powCap) >= 0 {
			intPart = intPart.Mod(powCap)
		}
	}
	truncatedAbs := intPart.Add(fracPart)
	_ = truncatedAbs

	// integer digits string zero padded to capInt
	intStr := intPart.StringFixed(0)
	// StringFixed may produce "0" for zero
	if intStr == "" {
		intStr = "0"
	}
	// remove possible minus sign (abs)
	if strings.HasPrefix(intStr, "-") {
		intStr = intStr[1:]
	}
	// intStr may contain decimal part if StringFixed(0) includes? it shouldn't
	if len(intStr) < capInt {
		intStr = strings.Repeat("0", capInt-len(intStr)) + intStr
	} else if len(intStr) > capInt {
		intStr = intStr[len(intStr)-capInt:]
	}

	// fractional part string
	fracStr := ""
	if decPlaces > 0 {
		powDec := pow10Decimal(int32(decPlaces))
		fracScaled := fracPart.Mul(powDec).Truncate(0)
		fracVal := fracScaled.Abs().IntPart()
		fracStr = fmt.Sprintf("%0*d", decPlaces, fracVal)
		// handle negative zero case
		if len(fracStr) > decPlaces {
			fracStr = fracStr[len(fracStr)-decPlaces:]
		}
	}

	var intResult strings.Builder
	intResult.Grow(len(intPat))
	stillSuppress := true
	digitIdx := 0
	digitsRunes := []rune(intStr)
	for _, ch := range intPat {
		if ch == 'Z' || ch == '9' {
			d := digitsRunes[digitIdx]
			digitIdx++
			if ch == 'Z' {
				if stillSuppress {
					if d == '0' {
						intResult.WriteRune(' ')
					} else {
						intResult.WriteRune(d)
						stillSuppress = false
					}
				} else {
					intResult.WriteRune(d)
				}
			} else { // '9'
				intResult.WriteRune(d)
				stillSuppress = false
			}
		} else if ch == ',' {
			if stillSuppress {
				intResult.WriteRune(' ')
			} else {
				intResult.WriteRune(',')
			}
		} else {
			intResult.WriteRune(ch)
		}
	}
	res := intResult.String()
	if decPlaces > 0 {
		res = res + "." + fracStr
	}
	if isNeg {
		// simple handling: replace first leading space with '-' if exists, otherwise prepend
		runes := []rune(res)
		placed := false
		for i, ch := range runes {
			if ch == ' ' {
				runes[i] = '-'
				placed = true
				break
			}
			if ch != ' ' && ch != ',' {
				// no leading space, need to insert minus
				break
			}
		}
		if placed {
			res = string(runes)
		} else {
			res = "-" + res
			if len(res) > len(pic) {
				res = res[len(res)-len(pic):]
			}
		}
	}
	return res
}

func formatCount(c int64) string {
	if c < 0 {
		c = -c
	}
	c = c % 1000
	return fmt.Sprintf("%03d", c)
}

func InputDone() bool {
	return WsEofFlag == "Y"
}

func ReadPara() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 13 {
			line = line + strings.Repeat(" ", 13-len(line))
		} else if len(line) > 13 {
			line = line[:13]
		}
		TaxRecGlobal.TrId = line[0:5]
		rawInc := line[5:13]
		TaxRecGlobal.TrIncome = parseIncome(rawInc)
	} else {
		WsEofFlag = "Y"
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
		}
	}
}

func ProcessPara() {
	if TaxRecGlobal.TrIncome.Cmp(const10000) <= 0 {
		expr := TaxRecGlobal.TrIncome.Mul(rate10)
		WsTax = storeNumeric(expr.Round(2), 7, 2)
	} else {
		if TaxRecGlobal.TrIncome.Cmp(const40000) <= 0 {
			diff := TaxRecGlobal.TrIncome.Sub(const10000)
			expr := const1000.Add(diff.Mul(rate20))
			WsTax = storeNumeric(expr.Round(2), 7, 2)
		} else {
			diff := TaxRecGlobal.TrIncome.Sub(const40000)
			expr := const7000.Add(diff.Mul(rate30))
			WsTax = storeNumeric(expr.Round(2), 7, 2)
		}
	}
	WsNet = storeNumeric(TaxRecGlobal.TrIncome.Sub(WsTax).Truncate(2), 7, 2)
	WsTotalTax = storeNumeric(WsTotalTax.Add(WsTax).Truncate(2), 9, 2)
	WsCount = (WsCount + 1) % 1000
	WsIncEd = formatEdited(TaxRecGlobal.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	line := TaxRecGlobal.TrId + " " + WsIncEd + " " + WsTaxEd + " " + WsNetEd
	fmt.Printf("%s\n", line)
	ReadPara()
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			WsEofFlag = "Y"
		} else {
			fmt.Fprintf(os.Stderr, "open error: %v\n", err)
			os.Exit(1)
		}
	} else {
		inputFile = f
		defer func() {
			f.Close()
			inputFile = nil
			scanner = nil
		}()
		scanner = bufio.NewScanner(f)
		const maxCapacity = 1024 * 1024
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, maxCapacity)
		ReadPara()
		for !InputDone() {
			ProcessPara()
		}
	}
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	countStr := formatCount(WsCount)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}

func main() {
	WsEofFlag = "N"
	WsTax = decimal.NewFromInt(0)
	WsNet = decimal.NewFromInt(0)
	WsTotalTax = decimal.NewFromInt(0)
	WsCount = 0
	MainPara()
}
